import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [accuracy, setAccuracy] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    testConnection();
  }, []);

  const handleFileSelect = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      setOriginalImage(ev.target.result);
      setProcessedImage(null);
      setAccuracy(null);
    };
    reader.readAsDataURL(file);
  };

  const processImage = async () => {
    setLoading(true);
    setError(null);

    try {
      const blob = await (await fetch(originalImage)).blob();
      const formData = new FormData();
      formData.append('image', blob);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const res = await axios.post(`${API_URL}/process-image`, formData);
      setProcessedImage(`data:image/png;base64,${res.data.processed_image}`);
      setAccuracy(res.data.accuracy);
    } catch (e) {
      setError("Processing failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <div className="upload-area" onClick={() => fileInputRef.current.click()}>
        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileSelect} />
        <p>Click to upload image</p>
      </div>

      <div className="image-preview" style={{ display: 'flex', gap: '20px' }}>
        {originalImage && (
          <div>
            <h3>Original</h3>
            <img src={originalImage} style={{ maxWidth: '100%', maxHeight: '350px' }} />
          </div>
        )}
        {processedImage && (
          <div>
            <h3>Processed</h3>
            <img src={processedImage} style={{ maxWidth: '100%', maxHeight: '350px' }} />
            <p style={{ fontWeight: 'bold', marginTop: '8px', color: '#2e7d32' }}>
              Filter Accuracy: {accuracy}%
            </p>
          </div>
        )}
      </div>

      {error && <p className="error">{error}</p>}

      <button onClick={processImage} disabled={loading || !originalImage}>
        {loading ? 'Processing...' : 'Process Image'}
      </button>
    </div>
  );
};

export default ImageProcessor;
